<div class="page">

  <div class="plate-label">PLATE 5.</div>

  <h1 class="st-james">ST. JAMES HALL,</h1>
  <div class="sunday-line">ON SUNDAY EVENING, FEBRUARY 23d, 1879.</div>

  <div class="farewell">FAREWELL TOUR!</div>
  <div class="absence-line">AFTER SIX YEARS ABSENCE IN FOREIGN COUNTRIES,</div>

